<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class Opportunity extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','customer_id','owner_id','name','state','stage','estimated_value','probability','currency','priority','lead_source','description','notes','next_follow_up_at','lost_reason','expected_close_at']; protected function casts():array{return ['estimated_value'=>'decimal:6','probability'=>'decimal:4','expected_close_at'=>'date','next_follow_up_at'=>'datetime'];} public function customer(){return $this->belongsTo(Customer::class);} public function owner(){return $this->belongsTo(User::class,'owner_id');} public function company(){return $this->belongsTo(Company::class);} public function branch(){return $this->belongsTo(Branch::class);} public function activities(){return $this->hasMany(CrmActivity::class);} public function stageHistory(){return $this->hasMany(CrmOpportunityStageHistory::class);} }
